def calculate_factorial(n):
    'Calculates the factorial of a non-negative integer n.'
    if not isinstance(n, int):
        raise TypeError('Input must be an integer.')
    if n < 0:
        raise ValueError('Input must be a non-negative integer.')

    if n == 0:
        return 1
    else:
        result = 1
        current_number = 1
        while current_number <= n:
            result *= current_number
            current_number += 1
        return result

if __name__ == '__main__':
    print(f'Factorial of 5 is: {calculate_factorial(5)}')
    print(f'Factorial of 0 is: {calculate_factorial(0)}')
    try:
        calculate_factorial(-3)
    except ValueError as e:
        print(f'Error for negative input: {e}')
    try:
        calculate_factorial(3.5)
    except TypeError as e:
        print(f'Error for non-integer input: {e}')
    print(f'Factorial of 7 is: {calculate_factorial(7)}')
    print(f'Factorial of 1 is: {calculate_factorial(1)}')

