import re

def find_longest_word(sentence):
    if not sentence:
        return ''

    words = re.findall(r'\b\w+\b', sentence.lower())
    if not words:
        return ''

    longest_word = ''
    max_length = 0

    for word in words:
        current_length = len(word)
        if current_length > max_length:
            max_length = current_length
            longest_word = word
        elif current_length == max_length and not longest_word: # handle first word case
            longest_word = word

    # Original case needs to be preserved for the output
    original_words = re.findall(r'\b\w+\b', sentence)
    for original_word in original_words:
        if original_word.lower() == longest_word:
            return original_word

    return '' # Should not be reached with valid input

