def fibonacci_sequence(n):
    if not isinstance(n, int) or n < 0:
        raise ValueError('Input must be a non-negative integer.')
    if n == 0:
        return []
    elif n == 1:
        return [0]
    elif n == 2:
        return [0, 1]

    sequence = [0, 1]
    a, b = 0, 1
    for _ in range(2, n):
        next_num = a + b
        sequence.append(next_num)
        a = b
        b = next_num
    return sequence

def main():
    print('Fibonacci sequence generator')
    try:
        num_elements = int(input('Enter the number of Fibonacci elements to generate: '))
        result = fibonacci_sequence(num_elements)
        print(f'The first {num_elements} Fibonacci numbers are: {result}')
        print('Operation complete.')
    except ValueError as e:
        print(f'Error: {e}')
        print('Please enter a valid integer.')

if __name__ == '__main__':
    main()

