def merge_dictionaries(dict1, dict2):
    '''
    Merges two dictionaries, with values from the second overriding the first.
    '''
    merged_dict = {}

    for key, value in dict1.items():
        merged_dict[key] = value

    for key, value in dict2.items():
        merged_dict[key] = value

    return merged_dict

if __name__ == '__main__':
    d1 = {'a': 1, 'b': 2, 'd': 'apple'}
    d2 = {'b': 3, 'c': 4, 'd': 'banana'}

    result = merge_dictionaries(d1, d2)
    print(f'Merged dictionary: {result}') 

    assert result == {'a': 1, 'b': 3, 'c': 4, 'd': 'banana'}, 'Test failed: incorrect merge'

    empty_d = {}
    another_d = {'x': 10, 'y': 'test'}

    result_empty = merge_dictionaries(empty_d, another_d)
    print(f'Empty merge: {result_empty}')
    assert result_empty == {'x': 10, 'y': 'test'}, 'Test failed: empty dict handling'

    print('All tests passed successfully!')

