def validate_email(email):
    'Validates a basic email format.'
    if not isinstance(email, str):
        return False

    if '@' not in email:
        return False

    if '.' not in email:
        return False

    at_index = email.find('@')
    dot_index = email.find('.')

    if at_index == -1 or dot_index == -1:
        return False

    if at_index > dot_index:
        return False

    if at_index == 0:
        return False

    if dot_index == len(email) - 1:
        return False

    if email.count('@') > 1:
        return False

    'All checks passed, it's a valid basic email.'
    return True

