import math

def geometric_mean(numbers):
    'Calculates the geometric mean of a list of positive numbers.'
    if not numbers:
        raise ValueError('Input list cannot be empty.')
    for num in numbers:
        if not isinstance(num, (int, float)):
            raise TypeError('All elements must be numbers.')
        if num <= 0:
            raise ValueError('All numbers must be positive.')

    product = 1.0
    for number in numbers:
        product *= number

    n = len(numbers)
    result = product ** (1.0 / n)
    return result

if __name__ == '__main__':
    print(f'Geometric mean of [2, 8] is: {geometric_mean([2, 8])}')
    print(f'Geometric mean of [1, 1, 1] is: {geometric_mean([1, 1, 1])}')
    print(f'Geometric mean of [2, 4, 8] is: {geometric_mean([2, 4, 8])}')
    try:
        geometric_mean([])
    except ValueError as e:
        print(f'Error caught as expected: {e}')
    try:
        geometric_mean([-1, 2])
    except ValueError as e:
        print(f'Error caught as expected: {e}')
    try:
        geometric_mean(['a', 2])
    except TypeError as e:
        print(f'Error caught as expected: {e}')

